import {Game, SHIPS, BUILDINGS, SECTORS, SCREEN_TYPES, distance} from './engine.js';
const SAVE='astra-dominion-save-v1';
let game;try{game=Game.restore(localStorage.getItem(SAVE))||new Game();}catch{game=new Game();}
let selected=null, tab='fleet', skillMode=false, modal=null, busy=false, sound=false, toastTimer, animation=null;
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>({command:'◈',fleet:'✦',citadel:'▥',campaign:'◎',help:'?',sound:sound?'♫':'♪'}[name]||name);
function ship(type,enemy=false){
  const shapes={
    aegis:'<path d="M15 40 38 30 57 24 105 40 57 56 38 50Z"/><path d="m35 30-3-16 20 14M35 50l-3 16 20-14"/>',
    spear:'<path d="m9 40 34-8 14-10 57 18-57 18-14-10Z"/><path d="m42 32-8-20 36 20M42 48l-8 20 36-20"/>',
    mend:'<path d="m17 40 14-18 33 7 31 11-31 11-33 7Z"/><path d="m35 24 7-12 28 16M35 56l7 12 28-16"/><circle cx="52" cy="40" r="9"/>',
    crown:'<path d="m8 40 22-18 42 6 39 12-39 12-42 6Z"/><path d="m29 22-4-12 50 15M29 58l-4 12 50-15M20 30l-6-12 25 9M20 50l-6 12 25-9"/>'
  };
  return `<svg class="ship ${enemy?'hostile':''}" viewBox="0 0 120 80" aria-hidden="true"><g fill="${enemy?'#b76d65':SHIPS[type].color}" stroke="${enemy?'#f0bca2':'#e4d7ae'}" stroke-width="1.3" stroke-linejoin="round">${shapes[type]}<path d="m35 40 22-6 33 6-33 6Z" fill="${enemy?'#633332':'#285563'}"/><path d="M48 40h41" fill="none" stroke="#f5e5b9"/><path d="M15 35 2 40l13 5" fill="${enemy?'#db8a6b':'#9ee8db'}" stroke="none"/></g></svg>`;
}
function persist(){if(busy)return;try{localStorage.setItem(SAVE,game.serialize());}catch{toast('Browser storage is unavailable. Keep this tab open to preserve progress.');}}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
function tone(freq=420){if(!sound)return;try{const ctx=new (window.AudioContext||window.webkitAudioContext)(),o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(freq,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.65,ctx.currentTime+.15);g.gain.setValueAtTime(.055,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.2);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.2);o.onended=()=>ctx.close();}catch{}}
function doAction(fn){const err=fn();if(err){toast(err);tone(160);}else{tone();persist();}render();}
function resources(){const s=game.s;return `<div class="resource"><span class="resource-icon">◈</span><div><small>CREDITS</small><b>${s.credits.toLocaleString()}</b></div><em>+${game.income.credits}/op</em></div><div class="resource"><span class="resource-icon alloy">⬡</span><div><small>ALLOYS</small><b>${s.alloy}</b></div><em>+${game.income.alloy}/op</em></div><div class="resource hull"><span class="resource-icon">◇</span><div><small>CITADEL HULL</small><b>${s.integrity}<i>%</i></b></div><span class="mini-meter"><span style="width:${s.integrity}%"></span></span></div>`;}
function render(){
  const s=game.s,battle=s.phase==='battle',prep=s.phase==='prep',sector=game.sector;
  $('#app').innerHTML=`
  <aside class="rail"><a class="sigil" href="#" aria-label="Astra Dominion command"><img src="./assets/emblem.svg" alt=""></a><div class="rail-line"></div>${['command','fleet','citadel','campaign'].map((k,i)=>`<button class="rail-button ${(k===tab||(k==='command'&&tab==='fleet'))?'active':''}" data-nav="${k}" title="${['Command deck','Your fleet','Citadel infrastructure','Campaign map'][i]}" aria-label="${k}">${icon(k)}<span>${k==='command'?'DECK':k==='citadel'?'BASE':k.toUpperCase()}</span></button>`).join('')}<div class="rail-bottom"><button data-action="help" class="rail-button" aria-label="How to play">?<span>GUIDE</span></button><span class="rail-version">AD / 01</span></div></aside>
  <div class="shell ${battle?'battle-mode':''}"><header class="topbar"><div class="brand"><span>ASTRA <strong>DOMINION</strong></span><small>AURELIAN FLEET COMMAND</small></div><div class="resources">${resources()}</div><div class="header-actions"><button class="icon-button ${sound?'on':''}" data-action="sound" aria-label="${sound?'Disable':'Enable'} sound" title="Toggle sound">${icon('sound')}</button><button class="icon-button" data-action="settings" aria-label="Game settings" title="Game settings">⚙</button><div class="profile" title="Admiral Lyra Voss"></div></div></header>
  <main><section class="hero"><div class="hero-art"></div><div class="hero-shade"></div><div class="hero-content"><div class="eyebrow"><span></span> OPERATION ${String(s.sector+1).padStart(2,'0')} <i>/</i> ${sector.region}</div><h1>${sector.name}</h1><p>${sector.subtitle}</p><div class="hero-tags"><span>◈ &nbsp; SECTOR ${s.sector+1} OF 6</span><span>✦ &nbsp; ${prep?game.deployed.length:game.allies.length} SHIPS ${prep?'ASSIGNED':'ACTIVE'}</span><span class="threat">◇ &nbsp; ${s.sector<2?'MODERATE':s.sector<4?'ELEVATED':'CRITICAL'} THREAT</span></div></div><div class="hero-seal"><div>✦</div><span>PER ASPERA<br>AD ASTRA</span></div><div class="hero-caption">AURELIA STATION <span>•</span> ORBITAL COMMAND</div></section>
  <div class="phasebar"><div class="phase-item ${prep?'current':'done'}"><span class="phase-number">${prep?'01':'✓'}</span><div><b>Preparation</b><small>BUILD · RECRUIT · DEPLOY</small></div></div><span class="phase-connector"></span><div class="phase-item ${battle?'current':''}"><span class="phase-number">02</span><div><b>Engagement</b><small>COMMAND YOUR FLEET</small></div></div><span class="phase-connector"></span><div class="phase-item ${!battle&&!prep?'current':''}"><span class="phase-number">03</span><div><b>Aftermath</b><small>RECOVER · ADVANCE</small></div></div><div class="phase-status"><span class="status-dot ${battle?'live':''}"></span>${battle?`ROUND ${s.round} / 12 · ${s.turn==='player'?'YOUR TURN':'ENEMY TURN'}`:prep?'AWAITING YOUR ORDERS':'OPERATION CONCLUDED'}</div></div>
  <div class="command-grid"><div class="primary-column"><section class="panel battlefield-panel"><div class="panel-heading"><div><span class="eyebrow">TACTICAL OVERVIEW</span><h2>${battle?'Engagement zone':'Deployment zone'}</h2></div><div class="battle-label"><span class="status-dot"></span> ${battle?'LIVE FEED':'TACTICAL PROJECTION'}</div></div><div class="battlefield"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="map-labels"><span>AURELIAN FORMATION</span><span>NO MAN’S SPACE</span><span>HOSTILE SIGNATURES</span></div><div class="board" role="group" aria-label="Tactical battlefield">${board()}</div><div class="map-bottom"><span>HEL / ${String(s.sector+1).padStart(2,'0')} &nbsp; 23.48 : 09.16</span><div><i class="friendly-key"></i> FRIENDLY <i class="enemy-key"></i> ENEMY</div></div></div><div class="board-instructions"><span>ⓘ</span><p>${battle?(skillMode?'ABILITY ARMED — select an enemy within range.':selected?'Click an adjacent empty tile to move, or an enemy in range to fire.':'Select a friendly ship to give orders. Each ship has 2 actions per round.'):'Select a ship below, then click a friendly tile to position it. Occupied tiles swap ships.'}</p>${prep?`<div class="deployment-actions">${game.deployed.some(u=>u.id===selected)?'<button class="text-button" data-action="reserve">Return to reserve</button>':''}<button class="text-button" data-action="auto">Auto deploy ↗</button></div>`:`<span class="energy">✧ ${s.energy} ENERGY</span>`}</div>${battle?battleControls():''}<div class="tactics-legend"><strong>SCREENED</strong> · Aegis / Crown intercept 50% of head-on fire for ships 1–2 tiles behind. Change lanes to flank. Enemy arrows show current intent.</div></section>
  <section class="panel hangar"><div class="tabs"><button data-tab="fleet" class="${tab==='fleet'?'active':''}">Fleet <span>${s.fleet.length}/${game.capacity}</span></button><button data-tab="citadel" class="${tab==='citadel'?'active':''}">Citadel</button><button data-tab="campaign" class="${tab==='campaign'?'active':''}">Campaign</button><div>${prep?'PREPARATION SYSTEMS ONLINE':'CONSTRUCTION LOCKED DURING COMBAT'}</div></div><div class="tab-content">${tab==='citadel'?buildings():tab==='campaign'?campaign():fleet()}</div></section></div>
  <aside class="secondary-column">${advisor()}${operationCard()}<section class="panel dispatch"><div class="small-heading"><span>COMMAND LOG</span><span>↘</span></div><div class="log-list" role="log">${s.log.slice(0,4).map((x,i)=>`<div class="log-entry"><span>${String(s.log.length-i).padStart(2,'0')}</span><p>${esc(x)}</p></div>`).join('')}</div></section></aside></div>
  <footer><span>✦ &nbsp; THE AURELIAN CONCORD</span><span id="save-status">CAMPAIGN SAVED LOCALLY <i>•</i> ${sound?'AUDIO ON':'AUDIO OFF'}</span><button data-action="help">FIELD MANUAL ↗</button></footer></main>${battle?`<div class="mobile-combat-bar"><span>ROUND ${s.round}<small>✧ ${s.energy} ENERGY · ${game.allies.reduce((n,u)=>n+u.ap,0)} ACTIONS LEFT</small></span><button class="primary-button" data-action="end-mobile" ${busy?'disabled':''}>${busy?'ENEMY TURN…':'END ROUND →'}</button></div>`:''}</div>${dialog()}`;
  if(animation){const target=document.querySelector(`[data-unit="${animation}"]`);target?.classList.add('hit');}
  if(modal||['result','complete','defeat'].includes(s.phase))setTimeout(()=>$('.modal button')?.focus(),0);
}
function board(){
  const s=game.s,prep=s.phase==='prep';
  const list=prep?[...game.deployed.map(u=>({...u,side:'ally'})),...game.sector.enemies.map((type,i)=>({id:`preview${i}`,type,side:'enemy',row:i%3,col:i<3?5:6}))]:s.units.filter(u=>u.hp>0);
  const active=list.find(u=>u.id===selected&&u.side==='ally');
  return Array.from({length:21},(_,i)=>{
    const row=Math.floor(i/7),col=i%7,u=list.find(x=>x.row===row&&x.col===col),enemy=u?.side==='enemy',chosen=u?.id===selected;
    const protector=u?game.screenFor(u,null,list):null;
    const plan=enemy&&!prep&&s.phase==='battle'?game.enemyPlan(u):null;
    const intended=list.find(x=>x.id===plan?.targetId);
    let potential='';
    if(active&&!prep&&active.ap>0&&s.turn==='player'){if(!u&&distance(active,{row,col})===1)potential=' reachable';if(enemy&&distance(active,u)<=active.range)potential=' targetable';}
    const label=u?`${enemy?'Enemy':'Friendly'} ${SHIPS[u.type].name}${prep?'':`, ${u.hp} hull`}, lane ${row+1}, column ${col+1}`:`Empty tile, lane ${row+1}, column ${col+1}${prep&&col<3?', deployment zone':''}`;
    let details=protector?` Screened by ${SHIPS[protector.type].name} at ${'ABC'[protector.row]}${protector.col+1}: intercepts 50% of head-on damage. Flank attacks bypass screening.`:'';
    if(u?.taunting)details+=' Draw Fire active until the next player round.';
    if(intended)details+=` Enemy intent: ${SHIPS[intended.type].name} at ${'ABC'[intended.row]}${intended.col+1}${plan.drawn?' (Draw Fire)':''}. Re-evaluated before acting.`;
    if(enemy&&active&&potential===' targetable'){
      const piercing=skillMode&&active.type==='spear';
      const hit=game.previewDamage(active,u,Math.round(active.attack*(skillMode?SHIPS[active.type].skillMultiplier||1:1)),piercing,piercing);
      const screen=list.find(x=>x.id===hit.protectorId);
      details+=` Attack preview: ${hit.targetDamage} damage to target${screen?`, ${hit.protectorDamage} intercepted by ${SHIPS[screen.type].name}`:''}, before shields.`;
    }
    const status=u?.taunting?'BEACON':protector?'SCREENED':'';
    return `<button class="cell ${col<3?'friendly-cell':col>3?'enemy-cell':'neutral-cell'} ${u?'occupied':''} ${enemy?'enemy':''} ${chosen?'selected':''} ${protector?'screened':''} ${u?.taunting?'beacon-active':''}${potential}" data-cell="${row},${col}" ${u?`data-unit="${u.id}"`:''} ${protector?`data-screen="${protector.id}"`:''} ${intended?`data-intent="${intended.id}"`:''} title="${esc(label+details)}" aria-label="${esc(label+details)}" ${chosen?'aria-pressed="true"':''}>
      <span class="cell-coordinate">${'ABC'[row]}${col+1}</span>${status?`<span class="formation-status">${status}</span>`:''}
      ${u?`${ship(u.type,enemy)}<span class="unit-name">${SHIPS[u.type].name.split(' ')[0]}${u.guard?' ◇':''}</span>${prep?`<span class="unit-role">${enemy?'HOSTILE':SHIPS[u.type].role.toUpperCase()}</span>`:`<span class="unit-health"><span style="width:${u.hp/u.maxHp*100}%"></span></span><span class="unit-meta">${u.hp}${u.shield?' +'+u.shield+'◇':''}<span class="${plan?.drawn?'drawn-intent':''}">${!enemy?'●'.repeat(u.ap)+'○'.repeat(2-u.ap):intended?`→ ${'ABC'[intended.row]}${intended.col+1}`:'MOVE'}</span></span>`}`:col<3&&prep?'<span class="deploy-plus">+</span>':''}
    </button>`;
  }).join('');
}
function fleet(){
  const s=game.s,prep=s.phase==='prep';
  return `<div class="fleet-subhead"><p>${prep?'Your ships. Your formation.':'Every order shapes the battle.'}<span>${prep?'Select a ship to position it on the tactical grid.':'Select a surviving ship to view its actions.'}</span></p><span class="small-label">${game.deployed.length} ASSIGNED / ${s.fleet.filter(x=>x.row===null).length} IN RESERVE</span></div><div class="roster">${s.fleet.map(u=>{const live=s.units.find(x=>x.id===u.id);return `<button class="roster-card ${selected===u.id?'chosen':''} ${!prep&&live?.hp===0?'destroyed':''}" data-select="${u.id}" ${!prep&&(!live||live.hp===0)?'disabled':''}><div class="roster-top"><span>${SHIPS[u.type].role}</span><i>${u.row!==null?'DEPLOYED':'RESERVE'}</i></div>${ship(u.type)}<b>${SHIPS[u.type].name}</b><div class="ship-stats"><span>◇ ${SHIPS[u.type].hp}</span><span>⌁ ${SHIPS[u.type].attack}</span><span>◎ ${SHIPS[u.type].range}</span></div><small>${u.kills>=2?'★ VETERAN · ':''}${u.row===null?'Awaiting assignment':`POSITION ${'ABC'[u.row]}${u.col+1}`}</small></button>`;}).join('')}</div>${prep?`<div class="recruit-heading"><span>COMMISSION REINFORCEMENTS</span><span>HULL / FIREPOWER / RANGE</span></div><div class="recruits">${Object.entries(SHIPS).map(([k,v])=>`<button data-recruit="${k}" class="recruit-card" ${s.fleet.length>=game.capacity||s.credits<game.price(k)||s.alloy<v.alloy?'disabled':''} title="${v.description}"><div>${ship(k)}</div><span><b>${v.name}</b><small>${v.role} · ${v.hp} / ${v.attack} / ${v.range}</small><em>◈ ${game.price(k)} <i>⬡ ${v.alloy}</i></em></span><strong>+</strong></button>`).join('')}</div>`:''}`;
}
function buildings(){const s=game.s;return `<div class="fleet-subhead"><p>The citadel provides.<span>Infrastructure generates income after every operation, including retreats.</span></p></div><div class="buildings">${Object.entries(BUILDINGS).map(([k,b])=>{const level=s.buildings[k],cost=b.cost+level*70,alloy=b.alloy+level*15;return `<div class="building"><span class="building-icon">${b.icon}</span><div><h3>${b.name}<span>${'◆'.repeat(level)}${'◇'.repeat(b.max-level)}</span></h3><p>${b.description}</p><button data-build="${k}" ${s.phase!=='prep'||level>=b.max||s.credits<cost||s.alloy<alloy?'disabled':''}>${level===b.max?'MAXIMUM LEVEL':`${level?'Upgrade':'Construct'} <span>◈ ${cost} &nbsp; ⬡ ${alloy}</span>`}</button></div></div>`;}).join('')}</div><div class="repair-row"><div><b>Citadel hull · ${s.integrity}%</b><span>Restore 30 integrity between operations.</span></div><button data-action="repair" class="secondary-button" ${s.phase!=='prep'||s.integrity===100||s.credits<90||s.alloy<20?'disabled':''}>Repair · ◈ 90 / ⬡ 20</button></div>`;}
function campaign(){return `<div class="fleet-subhead"><p>Reclaim the Aurelian frontier.<span>Six operations. One home worth defending.</span></p></div><div class="campaign-path">${SECTORS.map((sec,i)=>`<div class="campaign-sector ${i===game.s.sector?'current':''} ${i<game.s.sector?'cleared':''}"><span>${i<game.s.sector?'✓':String(i+1).padStart(2,'0')}</span><div><small>${sec.region}</small><h3>${sec.name}</h3><p>${sec.enemies.length} enemy vessels · ◈ ${sec.reward} victory bounty</p></div><em>${i<game.s.sector?'SECURED':i===game.s.sector?'ACTIVE':'LOCKED'}</em></div>`).join('')}</div>`;}
function advisor(){const battle=game.s.phase==='battle';return `<section class="panel advisor"><div class="advisor-image"><div class="advisor-label"><span class="status-dot"></span> COMMAND UPLINK</div></div><div class="advisor-copy"><small>YOUR FIRST OFFICER</small><h2>Lyra Voss <span>✦</span></h2><p>“${battle?'Keep our lancers at range. Move the line forward, and let the Halo tend to the wounded.':'A strong fleet begins before the first shot. Invest in our citadel, then give every ship a place in the formation.'}”</p><div class="advisor-signature">ADMIRALTY · AURELIAN CONCORD</div></div></section>`;}
function operationCard(){const s=game.s,battle=s.phase==='battle';return `<section class="panel operation-card"><div class="small-heading"><span>${battle?'BATTLE ORDERS':'MISSION BRIEF'}</span><span>◇</span></div><h3>Secure the sector</h3><p>Eliminate all hostile ships within 12 rounds. Protect the citadel.</p><div class="brief-row"><span>Hostile vessels</span><b>${battle?game.enemies.length:game.sector.enemies.length} <small>CONFIRMED</small></b></div><div class="brief-row"><span>Victory bounty</span><b class="gold">◈ ${game.sector.reward}</b></div><div class="brief-row"><span>Operation income</span><b>◈ ${game.income.credits} &nbsp; ⬡ ${game.income.alloy}</b></div>${battle?`<button data-action="end" class="primary-button" ${busy?'disabled':''}>${busy?'HOSTILE MANEUVERS…':'END ROUND'} <span>→</span></button><button data-action="retreat" class="retreat-button" ${busy?'disabled':''}>Withdraw fleet</button>`:`<button data-action="launch" class="primary-button" ${s.phase!=='prep'||!game.deployed.length?'disabled':''}>LAUNCH OPERATION <span>→</span></button><div class="launch-note">${game.deployed.length} ships ready · Formation will be locked</div>`}</section>`;}
function battleControls(){
  const u=game.allies.find(x=>x.id===selected);
  if(!u)return '<div class="battle-controls"><span>Select a ship to command it. Enemy arrows show intended targets; BEACON marks Draw Fire.</span></div>';
  const protector=game.screenFor(u),cover=game.allies.filter(a=>game.screenFor(a)?.id===u.id);
  const ability=SHIPS[u.type].skillMultiplier?`${SHIPS[u.type].skill}: ${Math.round(u.attack*SHIPS[u.type].skillMultiplier)} damage (two normal shots: ${u.attack*2}). ${u.type==='spear'?'Bypasses guard and screening.':''}`:SHIPS[u.type].description;
  return `<div class="battle-controls"><div class="selected-ship"><b>${SHIPS[u.type].name}</b><small>${u.hp}/${u.maxHp} HULL · ${u.attack} ATK · ${u.range} RANGE · ${u.ap} ACTIONS</small></div>
    <button class="secondary-button ${skillMode?'armed':''}" data-action="skill" title="${esc(ability)} Costs 2 actions and 1 energy; 2-round cooldown." ${busy||u.ap<2||u.cooldown>0||game.s.energy<1?'disabled':''}>${skillMode?'Cancel ability':SHIPS[u.type].skill}${u.cooldown?' · '+u.cooldown+'r':' · 1✧'}</button>
    ${SCREEN_TYPES.includes(u.type)?`<button class="secondary-button draw-fire ${u.taunting?'armed':''}" data-action="draw-fire" title="1 action + 1 energy. Enemies within 3 tiles target this ship if they can fire after at most one move. Lasts one enemy phase; separate 2-round cooldown." ${busy||u.ap<1||u.tauntCooldown>0||game.s.energy<1?'disabled':''}>${u.taunting?'Beacon active':`Draw Fire${u.tauntCooldown?' · '+u.tauntCooldown+'r':' · 1✧'}`}</button>`:''}
    <button class="secondary-button" data-action="guard" title="Spend remaining actions to reduce this ship’s incoming damage by 45%, including intercepted damage." ${busy||!u.ap?'disabled':''}>Guard ◇</button>
    <p class="combat-detail">${esc(ability)}${protector?` <span>Screened by ${SHIPS[protector.type].name} against head-on fire.</span>`:''}${cover.length?` <span>Screening ${cover.map(a=>`${SHIPS[a.type].name} (${'ABC'[a.row]}${a.col+1})`).join(', ')}.</span>`:''}${u.taunting?` <span>Beacon active · ${u.ap>0?'use your remaining action to Guard or reposition.':'expires at the next player round.'}</span>`:''}</p>
  </div>`;
}
function dialog(){
  const s=game.s;
  if(['result','complete','defeat'].includes(s.phase)){
    const r=s.result,finished=s.phase==='complete',dead=s.phase==='defeat';
    return `<div class="modal-backdrop"><section class="modal result-modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="result-emblem">${dead?'◇':'✦'}</div><span class="eyebrow">${finished?'THE AURELIAN CONCORD ENDURES':dead?'THE CITADEL HAS FALLEN':r.won?'OPERATION SUCCESSFUL':'REGROUP AT AURELIA'}</span><h2 id="dialog-title">${finished?'A new golden age.':dead?'The last light fades.':r.won?'Sector secured.':'The fight goes on.'}</h2><p>${finished?'Six sectors liberated. The frontier is home again, Admiral.':dead?'Your citadel has been destroyed. Begin a new campaign and forge a stronger fleet.':r.won?`${game.sector.name} is under Aurelian protection. Your surviving ships are fully repaired for the next operation.`:r.reason||'The enemy holds this sector. Rebuild your fleet and make another attempt.'}</p><div class="result-stats"><div><small>CREDITS EARNED</small><b>+${r.credits}</b></div><div><small>ALLOYS RECOVERED</small><b>+${r.alloy}</b></div><div><small>SHIPS LOST</small><b>${r.lost}</b></div></div>${finished||dead?`<p class="campaign-totals">${s.stats.victories} victories · ${s.stats.kills} hostiles neutralized · ${s.stats.losses} vessels lost</p><button class="primary-button" data-action="new">BEGIN NEW CAMPAIGN →</button>`:r.won?`<div class="salvage-heading">CHOOSE YOUR SECTOR REWARD</div><div class="reward-options"><button data-continue="credits"><span>◈</span><b>Treasury grant</b><small>+120 credits</small></button><button data-continue="alloy"><span>⬡</span><b>Salvage cache</b><small>+55 alloys</small></button><button data-continue="repair"><span>◇</span><b>Citadel relief</b><small>+25 integrity</small></button></div>`:`<button class="primary-button" data-continue="credits">RETURN TO PREPARATION →</button>`}</section></div>`;
  }
  if(!modal)return '';
  return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><button class="modal-close" data-action="close" aria-label="Close dialog">×</button>${modal==='help'?`<span class="eyebrow">AURELIAN OFFICER’S HANDBOOK</span><h2 id="dialog-title">Your first command.</h2><div class="guide-steps"><div><span>01</span><section><h3>Prepare your fleet</h3><p>Commission ships in Fleet. Select a ship, then a tile in the left three columns to deploy or reposition it. Auto deploy makes a balanced formation. Click a selected ship or its roster card again to deselect it. Use Return to reserve to undeploy it.</p></section></div><div><span>02</span><section><h3>Build a lasting advantage</h3><p>Citadel trade spires and foundries earn resources after each operation. Shields protect every ship, arsenals improve damage, and drydocks expand capacity.</p></section></div><div><span>03</span><section><h3>Make every order count</h3><p>Each ship has 2 actions per round. Click an adjacent empty tile to move (1 action), or a highlighted enemy to fire (1 action). Range counts horizontal and vertical tiles. Guard spends remaining actions to reduce damage by 45%.</p></section></div><div><span>04</span><section><h3>Turn the tide</h3><p>Solar lance deals 250% damage. Piercing ray deals 230% damage and bypasses guard and screening. Main abilities cost 2 actions + 1 energy with a 2-round cooldown. Draw Fire on an Aegis or Crown costs 1 action + 1 energy, lasts one enemy phase, and has its own 2-round cooldown. Enemies within 3 tiles target the beacon if they can reach firing range in at most one move. Combine it with Guard.</p></section></div><div><span>05</span><section><h3>Protect the line; attack the flank</h3><p>A living Aegis or Crown protects same-lane allies 1–2 tiles behind it. Against head-on fire from beyond the protector, it intercepts 50% of the damage. Guard and shields apply separately to each ship; screening does not chain. Shots from another lane bypass screening. These rules protect both fleets. Enemies prefer vulnerable targets in range; their arrows show current intent and update before they act.</p></section></div></div><div class="guide-footer">Win within 12 rounds. Lost ships are permanent; survivors heal between operations.<br>Six sectors to liberate. Progress saves automatically in this browser.<br><span>Keyboard: Tab + Enter to command · Escape cancels an ability or closes this guide</span></div><button class="primary-button" data-action="close">TAKE COMMAND →</button>`:modal==='retreat'?`<span class="eyebrow">TACTICAL WITHDRAWAL</span><h2 id="dialog-title">Fall back to Aurelia?</h2><p>Your surviving ships will be preserved. The citadel will lose ${18+game.enemies.length*4} integrity. You will receive operation income and can retry this sector.</p><button class="primary-button" data-action="confirm-retreat">WITHDRAW FLEET →</button><button class="secondary-button wide" data-action="close">Remain in battle</button>`:modal==='reset'?`<span class="eyebrow">NEW CAMPAIGN</span><h2 id="dialog-title">Begin again, Admiral?</h2><p>This replaces the campaign saved in this browser. Your current fleet and sector progress will be lost.</p><button class="primary-button" data-action="new">BEGIN NEW CAMPAIGN →</button><button class="secondary-button wide" data-action="settings">Keep current campaign</button>`:`<span class="eyebrow">COMMAND PREFERENCES</span><h2 id="dialog-title">Campaign settings</h2><p>Your campaign saves automatically on this device. No account or internet connection is required after the artwork loads.</p><button class="secondary-button wide" data-action="sound">${sound?'Disable':'Enable'} command sounds</button><button class="secondary-button wide" data-action="export">Export campaign save</button><button class="secondary-button wide" data-action="import">Import campaign save</button><button class="secondary-button wide danger" data-action="reset">Start a new campaign</button>`}</section></div>`;
}
async function endRound(){if(!game.beginEnemyTurn())return;busy=true;selected=null;skillMode=false;render();for(const enemy of [...game.enemies]){await new Promise(r=>setTimeout(r,420));if(game.s.phase!=='battle')break;const effect=game.enemyStep(enemy.id);animation=effect?.to;render();tone(220);}await new Promise(r=>setTimeout(r,320));game.nextRound();busy=false;animation=null;persist();render();}
$('#app').addEventListener('click',event=>{
 const el=event.target.closest('button,[data-nav]');if(!el||el.disabled)return;
 if(el.dataset.action==='sound'){sound=!sound;tone();render();return;}
 if(busy){if(el.dataset.action==='help'){modal='help';render();}else if(el.dataset.action==='close'){modal=null;render();}return;}
 if(el.dataset.nav){tab=el.dataset.nav==='command'?'fleet':el.dataset.nav;render();if(el.dataset.nav!=='command')$('.hangar').scrollIntoView({behavior:'smooth',block:'nearest'});return;}
 if(el.dataset.tab){tab=el.dataset.tab;render();return;}
 if(el.dataset.select){const id=Number(el.dataset.select);selected=selected===id?null:id;skillMode=false;render();return;}
 if(el.dataset.recruit){doAction(()=>{const err=game.recruit(el.dataset.recruit);if(!err){selected=game.s.fleet.at(-1).id;toast('Ship commissioned. Click a highlighted tile to deploy it.');}return err;});return;}
 if(el.dataset.build){doAction(()=>game.build(el.dataset.build));return;}
 if(el.dataset.continue){game.continue(el.dataset.continue);selected=null;tab='fleet';persist();render();return;}
 if(el.dataset.cell){
   const [row,col]=el.dataset.cell.split(',').map(Number);
   if(game.s.phase==='prep'){
     const u=game.deployed.find(x=>x.row===row&&x.col===col);
     if(u&&u.id===selected){selected=null;skillMode=false;render();}
     else if(selected!==null&&col<3)doAction(()=>game.deploy(selected,row,col));
     else if(u){selected=u.id;skillMode=false;render();}
     else toast(col>2?'Hostile territory. Deploy in the left three columns.':'Select a ship from your fleet first.');
   }else if(game.s.phase==='battle'){
     const u=game.s.units.find(x=>x.hp>0&&x.row===row&&x.col===col);
     if(u?.side==='ally'){selected=selected===u.id?null:u.id;skillMode=false;render();}
     else if(u?.side==='enemy'&&selected!==null){animation=u.id;doAction(()=>game.attack(selected,u.id,skillMode));skillMode=false;setTimeout(()=>{animation=null;render();},300);}
     else if(selected!==null&&!u)doAction(()=>game.move(selected,row,col));
     else toast('Select a friendly ship first.');
   }
   return;
 }
 const action=el.dataset.action;
 if(['help','settings','reset','retreat'].includes(action)){modal=action;render();return;}
 if(action==='close'){modal=null;render();return;}
 if(action==='new'){game=new Game();selected=null;modal=null;tab='fleet';persist();render();return;}
 if(action==='launch'){doAction(()=>game.startBattle());selected=null;render();return;}
 if(action==='auto'){game.autoDeploy();persist();render();toast('Fleet assigned to a balanced formation.');return;}
 if(action==='reserve'){if(game.s.phase==='prep'&&selected!==null){game.reserve(selected);selected=null;skillMode=false;persist();render();}return;}
 if(action==='repair'){doAction(()=>game.repair());return;}
 if(action==='end'||action==='end-mobile'){endRound();return;}
 if(action==='guard'){doAction(()=>game.guard(selected));return;}
 if(action==='draw-fire'){skillMode=false;doAction(()=>game.drawFire(selected));return;}
 if(action==='skill'){const u=game.allies.find(x=>x.id===selected);if(!u)return;if(['mend','crown'].includes(u.type)){doAction(()=>game.support(selected));}else{skillMode=!skillMode;render();}return;}
 if(action==='confirm-retreat'){modal=null;game.retreat();selected=null;persist();render();return;}
 if(action==='export'){const blob=new Blob([game.serialize()],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='astra-dominion-campaign.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(action==='import'){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{const restored=Game.restore(await input.files[0]?.text());if(!restored||restored.s.turn==='enemy'){toast('That save could not be loaded. Choose a valid campaign saved on your turn.');return;}game=restored;selected=null;modal=null;persist();render();toast('Campaign restored.');};input.click();}
});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){modal=null;skillMode=false;render();}if(event.key==='Tab'){const dlg=$('.modal');if(!dlg)return;const buttons=[...dlg.querySelectorAll('button:not([disabled])')];if(event.shiftKey&&document.activeElement===buttons[0]){event.preventDefault();buttons.at(-1).focus();}else if(!event.shiftKey&&document.activeElement===buttons.at(-1)){event.preventDefault();buttons[0].focus();}}});
// A browser closed during enemy animation resumes from the last player-turn snapshot.
if(game.s.turn==='enemy')game.s.turn='player';
render();persist();
